# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KURULUŞ DÖNEMİ MÜCADELELERİNE FARKLI KAYNAKLARIN BAKIŞI (TAR.10.2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">OSMANLI VE İSLAM KAYNAKLARI</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Temsilciler: Âşıkpaşazâde, Ahmedî, Neşrî, Oruç Bey, İbn Battûta</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Bakış Açısı: Gaza ve cihat ruhu, İslam\'ı yayma (i\'lây-ı kelimetullah)</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Fethedilen yerlerde adalet ve «istimâlet» (gönül kazanma)</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Anadolu beylikleriyle akrabalık, satın alma ve birlik siyaseti</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• İskân ve vakıf eserleriyle şehirlerin hızla şenlendirilmesi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">BİZANS VE BATI KAYNAKLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Temsilciler: Pachymeres, Kantakuzenos, Dukas, Chalkokondyles</text>\n  <text x="370" y="112" font-size="11.2" fill="#14532d">• Bakış Açısı: Bizans\'ın iç taht kavgaları ve tekfurların zafiyeti</text>\n  <text x="370" y="136" font-size="11.2" fill="#14532d">• Osmanlı ordusunun disiplini, hızı ve esnek ittifak diplomasisi</text>\n  <text x="370" y="160" font-size="11.2" fill="#14532d">• Balkan köylüsünün ağır feodal vergilerden Osmanlı\'ya sığınması</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• Haçlı ordularındaki komuta bölünmüşlüğü (Sırpsındığı, Niğbolu)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Tarihsel olaylar farklı kaynakların (Osmanlı ve Bizans/Batı) karşılaştırılmasıyla çok boyutlu yorumlanır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1402 ANKARA SAVAŞI, FETRET DEVRİ VE DEVLETİN TOPARLANMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">ANKARA SAVAŞI (1402) VE FETRET DEVRİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Taraflar: Osmanlı (Yıldırım Bayezid) — Timur İmparatorluğu</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• Sebep: Cihan hâkimiyeti, sığınan hükümdarlar ve beylikler</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Sonuç: Anadolu Türk siyasi birliği bozuldu (Karesi hariç)</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• İstanbul\'un fethi yaklaşık 50 yıl gecikti</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Fetret Devri (1402-1413): İsa, Süleyman, Musa, Mehmet Çelebiler</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">I. MEHMET (ÇELEBİ) DÖNEMİ (1413-1421)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Fetret Devri\'ne son verdi → «Devletin İkinci Kurucusu»</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Rumeli\'de istimâlet ve tımar sayesinde toprak kaybı yaşanmadı</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Saruhanoğulları, Aydın ve Menteşe\'de hâkimiyet yenilendi</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Düzmece Mustafa ve Şeyh Bedrettin isyanları bastırıldı</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• 1416 Çalı Bey Deniz Savaşı (Venedik\'le ilk deniz mücadelesi)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Fetret Devri\'nde Anadolu beylikleri ayrılırken Balkan uluslarının ayrılmaması, istimâlet (adalet/hoşgörü) politikasının kanıtıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">II. MURAT DÖNEMİ: VARNA (1444) VE II. KOSOVA (1448) ZAFERLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">EDİRNE-SEGEDİN ANTLAŞMASI VE VARNA (1444)</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Anadolu\'da Germiyanoğulları (vasiyetle) ve Aydın-Menteşe katıldı</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• 1444 Edirne-Segedin Antlaşması: Haçlılarla 10 yıllık barış</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• II. Murat tahtı 12 yaşındaki oğlu II. Mehmet\'e bıraktı</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Haçlılar antlaşmayı bozunca II. Murat ordunun başına geçti</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• 1444 Varna Savaşı: Kral Vladislav öldü, Haçlılar bozguna uğradı</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">II. KOSOVA SAVAŞI (1448) VE SONUÇLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Sebep: Hünyadi Yanoş liderliğindeki Haçlıların Varna\'nın öcünü</text>\n  <text x="370" y="108" font-size="10.8" fill="#064e3b">  almak ve Türkleri Balkanlar\'dan tamamen atmak istemesi</text>\n  <text x="370" y="130" font-size="11.2" fill="#064e3b">• Sonuç 1: Haçlı ordusu kesin bir yenilgiye uğratıldı</text>\n  <text x="370" y="152" font-size="11.2" fill="#064e3b">• Sonuç 2: Balkanların Türk yurdu olduğu kesinleşti (Miryokefalon gibi)</text>\n  <text x="370" y="174" font-size="11.2" fill="#064e3b">• Sonuç 3: Avrupalılar savunmaya çekildi, Bizans\'ın umudu kalmadı</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">1444 Varna ve 1448 II. Kosova zaferleri, 1453 İstanbul\'un Fethi öncesi Balkan güvenliğini sağlamıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
